#' Balance and Attrition
#'
#' 
#' @param data .
#' @param treat .
#' @param control .
#' @param covs .
#' @param block .
#' @param outcome .
#' @param nperm .
#' @param seed .
#' @param flag .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bal} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$joint} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$att} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$attj} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$bal$asDF}
#'
#' \code{as.data.frame(results$bal)}
#'
#' @export
exbalance <- function(
    data,
    treat,
    control = "",
    covs,
    block,
    outcome,
    nperm = 2000,
    seed = 1234,
    flag = 0.1,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exbalance requires jmvcore to be installed (restart may be required)")

    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(block)) block <- jmvcore::resolveQuo(jmvcore::enquo(block))
    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(block), block, NULL),
            `if`( ! missing(outcome), outcome, NULL))


    options <- exbalanceOptions$new(
        treat = treat,
        control = control,
        covs = covs,
        block = block,
        outcome = outcome,
        nperm = nperm,
        seed = seed,
        flag = flag,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exbalanceClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

